type WorkspaceTab = "requisitions" | "sourcing" | "invoices" | "payments";
type Notice = { type: "success" | "error"; text: string } | null;

const today = () => new Date().toISOString().slice(0, 10);
const money = (value?: string | null) => {
  const amount = Number(value ?? 0);
  if (!Number.isFinite(amount)) return "₹0";
  return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(amount);
};
const messageOf = (error: unknown, fallback: string) => {
  if (error instanceof Error) return error.message;
  if (typeof error === "object" && error !== null && "message" in error && typeof error.message === "string") return error.message;
  return fallback;
};

const statusClass: Record<string, string> = {
  draft: "border-white/10 bg-white/[0.05] text-white/45",
  submitted: "border-amber-500/25 bg-amber-500/10 text-amber-300",
  approved: "border-emerald-500/25 bg-emerald-500/10 text-emerald-300",
  rejected: "border-red-500/25 bg-red-500/10 text-red-300",
  converted: "border-cyan-500/25 bg-cyan-500/10 text-cyan-300",
  sent: "border-cyan-500/25 bg-cyan-500/10 text-cyan-300",
  responded: "border-violet-500/25 bg-violet-500/10 text-violet-300",
  awarded: "border-emerald-500/25 bg-emerald-500/10 text-emerald-300",
  received: "border-emerald-500/25 bg-emerald-500/10 text-emerald-300",
  matched: "border-cyan-500/25 bg-cyan-500/10 text-cyan-300",
  exception: "border-red-500/25 bg-red-500/10 text-red-300",
  awaitingApproval: "border-amber-500/25 bg-amber-500/10 text-amber-300",
  paid: "border-emerald-500/25 bg-emerald-500/10 text-emerald-300",
  failed: "border-red-500/25 bg-red-500/10 text-red-300",
  processing: "border-violet-500/25 bg-violet-500/10 text-violet-300",
};

function Badge({ value }: { value: string }) {
  return <span data-testid={`status-${value}`} className={cn("inline-flex rounded-full border px-2 py-0.5 text-[10px] font-semibold capitalize", statusClass[value] ?? statusClass.draft)}>{value.replaceAll("_", " ")}</span>;
}

function SkeletonRows({ columns = 5 }: { columns?: number }) {
  return <>{Array.from({ length: 5 }).map((_, row) => <tr key={row} className="border-b border-white/[0.045]">{Array.from({ length: columns }).map((__, col) => <td key={col} className="px-4 py-3"><div className={cn("h-3 animate-pulse rounded bg-white/[0.055]", col === 0 ? "w-24" : "w-20")} /></td>)}</tr>)}</>;
}

function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) {
  return <div className="flex min-h-[220px] flex-col items-center justify-center px-5 text-center">
    <div className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl border border-white/[0.08] bg-white/[0.035] text-white/30"><FileSearch className="h-5 w-5" /></div>
    <p className="text-sm font-medium text-white/65">{title}</p>
    <p className="mt-1 max-w-sm text-xs text-white/30">{detail}</p>
    {action}
  </div>;
}

function InlineNotice({ notice, onDismiss }: { notice: Notice; onDismiss: () => void }) {
  if (!notice) return null;
  return <div data-testid="mutation-feedback" className={cn("flex items-center gap-2 rounded-lg border px-3 py-2 text-xs", notice.type === "success" ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-300" : "border-red-500/20 bg-red-500/10 text-red-300")}>
    {notice.type === "success" ? <CheckCircle2 className="h-4 w-4 shrink-0" /> : <AlertTriangle className="h-4 w-4 shrink-0" />}
    <span className="flex-1">{notice.text}</span>
    <button data-testid="button-dismiss-feedback" onClick={onDismiss} className="text-current/60 hover:text-current"><X className="h-3.5 w-3.5" /></button>
  </div>;
}

function Panel({ children, className }: { children: ReactNode; className?: string }) {
  return <section className={cn("rounded-xl border border-white/[0.07] bg-[#0a0f1e]", className)}>{children}</section>;
}

function Modal({ title, eyebrow, onClose, children, wide = false }: { title: string; eyebrow: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#02040b]/80 p-4 backdrop-blur-sm">
    <div role="dialog" aria-modal="true" className={cn("max-h-[90dvh] w-full overflow-y-auto rounded-2xl border border-white/[0.1] bg-[#0b1122] shadow-2xl shadow-black/40", wide ? "max-w-2xl" : "max-w-lg")}>
      <div className="sticky top-0 z-10 flex items-start justify-between border-b border-white/[0.07] bg-[#0b1122]/95 px-5 py-4 backdrop-blur">
        <div><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-cyan-400/70">{eyebrow}</p><h2 className="mt-1 text-base font-semibold text-white">{title}</h2></div>
        <button data-testid="button-close-modal" onClick={onClose} className="rounded-lg p-1.5 text-white/35 hover:bg-white/[0.06] hover:text-white"><X className="h-4 w-4" /></button>
      </div>
      {children}
    </div>
  </div>;
}

function Field({ label, children, className }: { label: string; children: ReactNode; className?: string }) {
  return <label className={cn("block space-y-1.5", className)}><span className="text-[11px] font-medium text-white/45">{label}</span>{children}</label>;
}

function SelectField({ label, value, onChange, children, className }: { label: string; value: string; onChange: (value: string) => void; children: ReactNode; className?: string }) {
  return <Field label={label} className={className}><select data-testid={`select-${label.toLowerCase().replaceAll(" ", "-")}`} value={value} onChange={e => onChange(e.target.value)} className="h-9 w-full rounded-md border border-white/[0.1] bg-white/[0.045] px-2.5 text-xs text-white outline-none focus:border-cyan-400/50">{children}</select></Field>;
}

function FormActions({ busy, onClose, label }: { busy: boolean; onClose: () => void; label: string }) {
  return <div className="flex justify-end gap-2 border-t border-white/[0.07] px-5 py-4"><Button data-testid="button-cancel-form" type="button" variant="ghost" onClick={onClose} className="h-8 text-xs text-white/45 hover:bg-white/[0.06] hover:text-white">Cancel</Button><Button data-testid="button-submit-form" disabled={busy} className="h-8 gap-2 bg-[#2563eb] text-xs hover:bg-[#1d4ed8]">{busy && <Loader2 className="h-3.5 w-3.5 animate-spin" />}{label}</Button></div>;
}

function SummaryStrip({ summary, loading }: { summary: ReturnType<typeof useSourceToPaySummary>["data"]; loading: boolean }) {
  const s = summary?.data;
  const items = [
    { label: "Requisitions", value: s ? String(s.requisitions.total) : "—", sub: s ? `${s.requisitions.pendingApproval} awaiting approval` : "", icon: ClipboardCheck, tone: "text-amber-300 bg-amber-400/10" },
    { label: "Committed", value: s ? money(s.requisitions.committed) : "—", sub: "approved requisitions", icon: ShoppingCart, tone: "text-cyan-300 bg-cyan-400/10" },
    { label: "Invoice exceptions", value: s ? String(s.invoices.exceptions) : "—", sub: s ? `${s.invoices.awaitingApproval} awaiting approval` : "", icon: AlertTriangle, tone: "text-red-300 bg-red-400/10" },
    { label: "Outstanding", value: s ? money(s.invoices.outstanding) : "—", sub: s ? `${s.payments.pending} payments pending` : "", icon: CircleDollarSign, tone: "text-violet-300 bg-violet-400/10" },
  ];
  return <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{items.map(item => <div data-testid={`metric-${item.label.toLowerCase().replaceAll(" ", "-")}`} key={item.label} className="rounded-xl border border-white/[0.07] bg-[#0a0f1e] p-4"><div className="flex items-start justify-between gap-2"><div><p className="text-[11px] text-white/40">{item.label}</p>{loading ? <div className="mt-2 h-6 w-20 animate-pulse rounded bg-white/[0.06]" /> : <p className="mt-1 text-xl font-semibold tracking-tight text-white">{item.value}</p>}</div><div className={cn("flex h-8 w-8 items-center justify-center rounded-lg", item.tone)}><item.icon className="h-4 w-4" /></div></div>{!loading && <p className="mt-2 truncate text-[10px] text-white/30">{item.sub}</p>}</div>)}</div>;
}

function RequisitionForm({ open, edit, onClose, onSubmit, busy, error }: { open: boolean; edit: PurchaseRequisition | null; onClose: () => void; onSubmit: (value: PurchaseRequisitionFormValues) => void; busy: boolean; error: string | null }) {
  const [form, setForm] = useState<PurchaseRequisitionFormValues>({ department: "", costCenter: "", neededBy: today(), justification: "", lines: [{ description: "", unit: "EA", quantity: "1", estimatedUnitPrice: "0", taxRate: "0", sequence: 1 }] });
  useEffect(() => {
    if (!open) return;
    setForm({ department: edit?.department ?? "", costCenter: edit?.costCenter ?? "", neededBy: edit?.neededBy?.slice(0, 10) ?? today(), justification: edit?.justification ?? "", lines: [{ description: edit?.lines?.[0]?.description ?? "", unit: edit?.lines?.[0]?.unit ?? "EA", quantity: edit?.lines?.[0]?.quantity ?? "1", estimatedUnitPrice: edit?.lines?.[0]?.estimatedUnitPrice ?? "0", taxRate: edit?.lines?.[0]?.taxRate ?? "0", sequence: 1 }] });
  }, [open, edit]);
  if (!open) return null;
  const set = (key: keyof PurchaseRequisitionFormValues, value: string) => setForm(current => ({ ...current, [key]: value }));
  const setLine = (key: string, value: string) => setForm(current => ({ ...current, lines: [{ ...current.lines[0], [key]: value }] }));
  return <Modal title={edit ? "Edit requisition" : "New requisition"} eyebrow="Source" onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); onSubmit(form); }} className="space-y-4 p-5">
    <div className="grid gap-3 sm:grid-cols-2"><Field label="Department"><Input data-testid="input-requisition-department" required value={form.department} onChange={e => set("department", e.target.value)} placeholder="e.g. Operations" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Cost center"><Input data-testid="input-requisition-cost-center" value={form.costCenter ?? ""} onChange={e => set("costCenter", e.target.value)} placeholder="Optional" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div>
    <div className="grid gap-3 sm:grid-cols-2"><Field label="Needed by"><Input data-testid="input-requisition-needed-by" required type="date" value={form.neededBy} onChange={e => set("neededBy", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field><Field label="Justification"><Input data-testid="input-requisition-justification" required value={form.justification} onChange={e => set("justification", e.target.value)} placeholder="Why is this purchase needed?" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div>
    <div className="rounded-lg border border-white/[0.07] bg-white/[0.025] p-3"><p className="mb-3 text-[11px] font-semibold uppercase tracking-wider text-white/35">First line item</p><div className="grid gap-3 sm:grid-cols-[1fr_100px_120px]"><Field label="Description" className="sm:col-span-1"><Input data-testid="input-requisition-line-description" required value={form.lines[0].description} onChange={e => setLine("description", e.target.value)} placeholder="What is being purchased?" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Quantity"><Input data-testid="input-requisition-line-quantity" required type="number" min="0.01" step="any" value={form.lines[0].quantity} onChange={e => setLine("quantity", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Est. unit price"><Input data-testid="input-requisition-line-price" required type="number" min="0" step="any" value={form.lines[0].estimatedUnitPrice} onChange={e => setLine("estimatedUnitPrice", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div></div>
    {error && <p className="text-xs text-red-300">{error}</p>}<FormActions busy={busy} onClose={onClose} label={edit ? "Save changes" : "Create requisition"} />
  </form></Modal>;
}

function QuoteForm({ open, quote, rfqId, vendors, onClose, onSubmit, busy, error }: { open: boolean; quote: PurchaseQuote | null; rfqId: number; vendors: PurchaseVendor[]; onClose: () => void; onSubmit: (value: PurchaseQuoteFormValues) => void; busy: boolean; error: string | null }) {
  const [form, setForm] = useState<PurchaseQuoteFormValues>({ rfqId, vendorId: 0, quoteNumber: "", quoteDate: today(), validUntil: "", deliveryDays: null, paymentTerms: "", lines: [{ description: "", quantity: "1", unit: "EA", unitPrice: "0", taxRate: "0", sequence: 1 }] });
  useEffect(() => { if (open) setForm({ rfqId, vendorId: quote?.vendorId ?? 0, quoteNumber: quote?.quoteNumber ?? "", quoteDate: quote?.quoteDate?.slice(0, 10) ?? today(), validUntil: quote?.validUntil?.slice(0, 10) ?? "", deliveryDays: quote?.deliveryDays ?? null, paymentTerms: quote?.paymentTerms ?? "", lines: [{ description: quote?.lines?.[0]?.description ?? "", quantity: quote?.lines?.[0]?.quantity ?? "1", unit: quote?.lines?.[0]?.unit ?? "EA", unitPrice: quote?.lines?.[0]?.unitPrice ?? "0", taxRate: quote?.lines?.[0]?.taxRate ?? "0", sequence: 1 }] }); }, [open, quote, rfqId]);
  if (!open) return null;
  const update = (key: keyof PurchaseQuoteFormValues, value: string) => setForm(current => ({ ...current, [key]: key === "vendorId" ? Number(value) : key === "deliveryDays" ? (value ? Number(value) : null) : value }));
  const updateLine = (key: string, value: string) => setForm(current => ({ ...current, lines: [{ ...current.lines[0], [key]: value }] }));
  return <Modal title={quote ? "Edit supplier quote" : "Record supplier quote"} eyebrow="Source / Supplier quote" onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); onSubmit(form); }} className="space-y-4 p-5"><div className="grid gap-3 sm:grid-cols-2"><SelectField label="Supplier" value={String(form.vendorId || "")} onChange={v => update("vendorId", v)}><option value="">Select supplier</option>{vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</SelectField><Field label="Quote number"><Input data-testid="input-quote-number" required value={form.quoteNumber} onChange={e => update("quoteNumber", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Quote date"><Input data-testid="input-quote-date" required type="date" value={form.quoteDate} onChange={e => update("quoteDate", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field><Field label="Valid until"><Input data-testid="input-quote-valid-until" type="date" value={form.validUntil ?? ""} onChange={e => update("validUntil", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Delivery days"><Input data-testid="input-quote-delivery-days" type="number" min="0" value={form.deliveryDays ?? ""} onChange={e => update("deliveryDays", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Payment terms"><Input data-testid="input-quote-payment-terms" value={form.paymentTerms ?? ""} onChange={e => update("paymentTerms", e.target.value)} placeholder="e.g. Net 30" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div><div className="rounded-lg border border-white/[0.07] bg-white/[0.025] p-3"><p className="mb-3 text-[11px] font-semibold uppercase tracking-wider text-white/35">Quoted line</p><div className="grid gap-3 sm:grid-cols-[1fr_100px_120px]"><Field label="Description"><Input data-testid="input-quote-line-description" required value={form.lines[0].description} onChange={e => updateLine("description", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Quantity"><Input data-testid="input-quote-line-quantity" required type="number" min="0.01" step="any" value={form.lines[0].quantity} onChange={e => updateLine("quantity", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Unit price"><Input data-testid="input-quote-line-price" required type="number" min="0" step="any" value={form.lines[0].unitPrice} onChange={e => updateLine("unitPrice", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div></div>{error && <p className="text-xs text-red-300">{error}</p>}<FormActions busy={busy} onClose={onClose} label={quote ? "Save quote" : "Add quote"} /></form></Modal>;
}

function InvoiceForm({ open, orders, vendors, onClose, onSubmit, busy, error }: { open: boolean; orders: Array<{ id: number; poNumber: string; vendorId: number; vendorName: string }>; vendors: PurchaseVendor[]; onClose: () => void; onSubmit: (value: PurchaseInvoiceFormValues) => void; busy: boolean; error: string | null }) {
  const [form, setForm] = useState<PurchaseInvoiceFormValues>({ invoiceNumber: "", vendorId: 0, poId: null, invoiceDate: today(), dueDate: "", currency: "INR", notes: "", lines: [{ description: "", quantity: "1", unitPrice: "0", taxRate: "0", sequence: 1 }] });
  const { data: poDetail } = usePurchaseOrder(form.poId ?? 0);
  const selectedPo = poDetail?.data;
  useEffect(() => { if (open) setForm({ invoiceNumber: "", vendorId: 0, poId: null, invoiceDate: today(), dueDate: "", currency: "INR", notes: "", lines: [{ description: "", quantity: "1", unitPrice: "0", taxRate: "0", sequence: 1 }] }); }, [open]);
  if (!open) return null;
  const set = (key: keyof PurchaseInvoiceFormValues, value: string) => setForm(current => ({ ...current, [key]: key === "poId" ? (value ? Number(value) : null) : value }));
  return <Modal title="Record supplier invoice" eyebrow="Pay / Invoice intake" onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); onSubmit(form); }} className="space-y-4 p-5"><div className="grid gap-3 sm:grid-cols-2"><Field label="Invoice number"><Input data-testid="input-invoice-number" required value={form.invoiceNumber} onChange={e => set("invoiceNumber", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><SelectField label="Supplier" value={String(form.vendorId || "")} onChange={v => setForm(current => ({ ...current, vendorId: Number(v) }))}><option value="">Select supplier</option>{vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</SelectField><SelectField label="Purchase order" value={String(form.poId ?? "")} onChange={v => setForm(current => ({ ...current, poId: v ? Number(v) : null, vendorId: v ? (orders.find(o => o.id === Number(v))?.vendorId ?? current.vendorId) : current.vendorId, lines: [{ ...current.lines[0], poLineId: undefined }] }))}><option value="">Not linked</option>{orders.map(o => <option key={o.id} value={o.id}>{o.poNumber} · {o.vendorName}</option>)}</SelectField><Field label="Invoice date"><Input data-testid="input-invoice-date" required type="date" value={form.invoiceDate} onChange={e => set("invoiceDate", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field><Field label="Due date"><Input data-testid="input-invoice-due-date" type="date" value={form.dueDate ?? ""} onChange={e => set("dueDate", e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field></div><div className="rounded-lg border border-white/[0.07] bg-white/[0.025] p-3"><p className="mb-3 text-[11px] font-semibold uppercase tracking-wider text-white/35">Invoice line</p><div className="grid gap-3 sm:grid-cols-[1fr_100px_120px]"><Field label="Description"><Input data-testid="input-invoice-line-description" required value={form.lines[0].description} onChange={e => setForm(current => ({ ...current, lines: [{ ...current.lines[0], description: e.target.value }] }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Quantity"><Input data-testid="input-invoice-line-quantity" required type="number" min="0.01" step="any" value={form.lines[0].quantity} onChange={e => setForm(current => ({ ...current, lines: [{ ...current.lines[0], quantity: e.target.value }] }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Unit price"><Input data-testid="input-invoice-line-price" required type="number" min="0" step="any" value={form.lines[0].unitPrice} onChange={e => setForm(current => ({ ...current, lines: [{ ...current.lines[0], unitPrice: e.target.value }] }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field></div>{selectedPo?.lines?.length ? <SelectField label="PO line for matching" value={String(form.lines[0].poLineId ?? "")} onChange={v => setForm(current => ({ ...current, lines: [{ ...current.lines[0], poLineId: v ? Number(v) : null }] }))}><option value="">Select PO line</option>{selectedPo.lines.map(line => <option key={line.id} value={line.id}>{line.description} · {line.receivedQty}/{line.quantity} received</option>)}</SelectField> : null}</div>{error && <p className="text-xs text-red-300">{error}</p>}<FormActions busy={busy} onClose={onClose} label="Record invoice" /></form></Modal>;
}

function RequisitionsView({ canCreate, canEdit, canDelete, onNotice }: { canCreate: boolean; canEdit: boolean; canDelete: boolean; onNotice: (notice: Notice) => void }) {
  const [selected, setSelected] = useState<number | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [edit, setEdit] = useState<PurchaseRequisition | null>(null);
  const [rejecting, setRejecting] = useState<PurchaseRequisition | null>(null);
  const [rejectReason, setRejectReason] = useState("");
  const { data, isLoading, isError, refetch, isFetching } = usePurchaseRequisitions({ limit: 50 });
  const { data: detail } = usePurchaseRequisition(selected);
  const { data: vendorsRes } = usePurchaseVendors({ status: "active", limit: 200 });
  const create = useCreatePurchaseRequisition(); const update = useUpdatePurchaseRequisition(); const remove = useDeletePurchaseRequisition(); const approve = useApprovePurchaseRequisition(); const reject = useRejectPurchaseRequisition(); const convert = useConvertPurchaseRequisition();
  const rows = data?.data ?? []; const active = detail?.data ?? rows.find(r => r.id === selected) ?? null;
  const run = async (action: () => Promise<unknown>, success: string, fallback: string) => { try { await action(); onNotice({ type: "success", text: success }); } catch (e) { onNotice({ type: "error", text: messageOf(e, fallback) }); } };
  if (isError) return <ErrorState label="requisitions" onRetry={() => refetch()} />;
  return <div className="space-y-3"><Panel><Toolbar title="Demand intake" count={data?.total} loading={isFetching} onRefresh={() => refetch()} action={canCreate ? <Button data-testid="button-new-requisition" onClick={() => { setEdit(null); setFormOpen(true); }} size="sm" className="h-8 gap-1.5 bg-[#2563eb] text-xs hover:bg-[#1d4ed8]"><Plus className="h-3.5 w-3.5" /> New requisition</Button> : null} /><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-sm"><thead><tr className="border-b border-white/[0.05]">{["Requisition", "Department", "Needed by", "Estimate", "Status", ""].map(h => <th key={h} className="px-4 py-2.5 text-left text-[10px] font-semibold uppercase tracking-wider text-white/30">{h}</th>)}</tr></thead><tbody>{isLoading ? <SkeletonRows columns={6} /> : rows.length === 0 ? <tr><td colSpan={6}><EmptyState title="No requisitions yet" detail="Start with a clear request and preserve the approval trail." action={canCreate ? <button data-testid="button-empty-new-requisition" onClick={() => { setEdit(null); setFormOpen(true); }} className="mt-3 text-xs text-cyan-300 hover:text-cyan-200">Create first requisition</button> : undefined} /></td></tr> : rows.map(row => <tr data-testid={`row-requisition-${row.id}`} key={row.id} onClick={() => setSelected(row.id)} className={cn("group cursor-pointer border-b border-white/[0.045] transition-colors hover:bg-white/[0.025]", selected === row.id && "bg-cyan-400/[0.035]")}><td className="px-4 py-3"><p className="font-mono text-xs font-semibold text-cyan-300">{row.requisitionNumber}</p><p className="mt-0.5 max-w-[170px] truncate text-[11px] text-white/35">{row.justification}</p></td><td className="px-4 py-3 text-xs text-white/65">{row.department}</td><td className="px-4 py-3 text-xs text-white/45">{row.neededBy?.slice(0, 10)}</td><td className="px-4 py-3 text-right text-xs font-semibold tabular-nums text-white/75">{money(row.estimatedAmount)}</td><td className="px-4 py-3"><Badge value={row.status} /></td><td className="px-4 py-3"><div className="flex items-center justify-end gap-1 opacity-0 transition-opacity group-hover:opacity-100">{canEdit && row.status === "draft" && <button data-testid={`button-edit-requisition-${row.id}`} onClick={e => { e.stopPropagation(); setEdit(row); setFormOpen(true); }} className="rounded-md p-1.5 text-white/35 hover:bg-white/[0.08] hover:text-white"><Pencil className="h-3.5 w-3.5" /></button>}{canDelete && row.status === "draft" && <button data-testid={`button-delete-requisition-${row.id}`} onClick={e => { e.stopPropagation(); if (window.confirm(`Delete ${row.requisitionNumber}?`)) void run(() => remove.mutateAsync(row.id), "Requisition deleted", "Could not delete requisition"); }} className="rounded-md p-1.5 text-white/35 hover:bg-red-500/10 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button>}<ChevronDown className="h-4 w-4 rotate-[-90deg] text-white/20" /></div></td></tr>)}</tbody></table></div></Panel>
    {active && <Panel className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-white/[0.07] px-4 py-4"><div><p className="font-mono text-xs text-cyan-300">{active.requisitionNumber}</p><h3 className="mt-1 text-sm font-semibold text-white">{active.justification}</h3><p className="mt-1 text-xs text-white/35">{active.department} · Needed {active.neededBy?.slice(0, 10)}</p></div><div className="flex items-center gap-2"><Badge value={active.status} /><button data-testid="button-close-requisition-detail" onClick={() => setSelected(null)} className="rounded-md p-1 text-white/30 hover:text-white"><X className="h-4 w-4" /></button></div></div><div className="flex flex-wrap gap-2 px-4 py-3">{canEdit && active.status === "draft" && <Button data-testid={`button-submit-requisition-${active.id}`} onClick={() => void run(() => update.mutateAsync({ id: active.id, data: { status: "submitted" } }), "Requisition submitted for approval", "Could not submit requisition")} size="sm" className="h-8 gap-1.5 bg-amber-500/15 text-xs text-amber-200 hover:bg-amber-500/25"><Send className="h-3.5 w-3.5" /> Submit for approval</Button>}{canEdit && active.status === "submitted" && <><Button data-testid={`button-approve-requisition-${active.id}`} onClick={() => void run(() => approve.mutateAsync(active.id), "Requisition approved", "Could not approve requisition")} size="sm" className="h-8 gap-1.5 bg-emerald-500/15 text-xs text-emerald-200 hover:bg-emerald-500/25"><Check className="h-3.5 w-3.5" /> Approve</Button><Button data-testid={`button-reject-requisition-${active.id}`} onClick={() => setRejecting(active)} size="sm" variant="outline" className="h-8 gap-1.5 border-red-500/20 bg-transparent text-xs text-red-200 hover:bg-red-500/10"><XCircle className="h-3.5 w-3.5" /> Reject</Button></>}{canCreate && active.status === "approved" && <ConvertButton requisition={active} vendors={vendorsRes?.data ?? []} onConvert={vendorId => run(() => convert.mutateAsync({ id: active.id, vendorId }), "Requisition converted to purchase order", "Could not convert requisition")} />}</div>{active.lines?.length ? <div className="border-t border-white/[0.05] px-4 py-3"><p className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-white/30">Requested lines</p>{active.lines.map(line => <div key={line.id} className="flex items-center justify-between border-b border-white/[0.04] py-2 text-xs last:border-0"><span className="text-white/65">{line.description}</span><span className="tabular-nums text-white/40">{line.quantity} {line.unit} · {money(line.totalEstimate)}</span></div>)}</div> : null}</Panel>}
    <RequisitionForm open={formOpen} edit={edit} onClose={() => setFormOpen(false)} busy={create.isPending || update.isPending} error={create.error ? messageOf(create.error, "Could not create requisition") : update.error ? messageOf(update.error, "Could not update requisition") : null} onSubmit={value => void run(async () => { if (edit) await update.mutateAsync({ id: edit.id, data: value }); else await create.mutateAsync(value); setFormOpen(false); }, edit ? "Requisition updated" : "Requisition created", edit ? "Could not update requisition" : "Could not create requisition")} />
    {rejecting && <Modal title={`Reject ${rejecting.requisitionNumber}`} eyebrow="Approval control" onClose={() => setRejecting(null)}><form onSubmit={e => { e.preventDefault(); void run(() => reject.mutateAsync({ id: rejecting.id, reason: rejectReason }), "Requisition rejected", "Could not reject requisition").then(() => setRejecting(null)); }} className="space-y-4 p-5"><Field label="Reason"><Input data-testid="input-requisition-rejection-reason" required value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder="Explain the decision for the audit trail" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field>{reject.error && <p className="text-xs text-red-300">{messageOf(reject.error, "Could not reject requisition")}</p>}<FormActions busy={reject.isPending} onClose={() => setRejecting(null)} label="Reject requisition" /></form></Modal>}
  </div>;
}

function ConvertButton({ requisition, vendors, onConvert }: { requisition: PurchaseRequisition; vendors: PurchaseVendor[]; onConvert: (vendorId: number) => Promise<void> }) {
  const [vendorId, setVendorId] = useState("");
  return <div className="flex items-center gap-1.5"><select data-testid={`select-convert-vendor-${requisition.id}`} value={vendorId} onChange={e => setVendorId(e.target.value)} className="h-8 max-w-[160px] rounded-md border border-white/[0.1] bg-white/[0.045] px-2 text-xs text-white"><option value="">Select supplier</option>{vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</select><Button data-testid={`button-convert-requisition-${requisition.id}`} disabled={!vendorId} onClick={() => void onConvert(Number(vendorId))} size="sm" className="h-8 gap-1.5 bg-cyan-500/15 text-xs text-cyan-200 hover:bg-cyan-500/25"><ArrowRight className="h-3.5 w-3.5" /> Convert to PO</Button></div>;
}

function SourcingView({ canCreate, canEdit, onNotice }: { canCreate: boolean; canEdit: boolean; onNotice: (notice: Notice) => void }) {
  const [selected, setSelected] = useState<number | null>(null);
  const [inviteOpen, setInviteOpen] = useState(false); const [quoteOpen, setQuoteOpen] = useState(false); const [editQuote, setEditQuote] = useState<PurchaseQuote | null>(null); const [award, setAward] = useState<PurchaseQuote | null>(null); const [awardReason, setAwardReason] = useState("");
  const [vendorIds, setVendorIds] = useState<number[]>([]);
  const { data, isLoading, isError, refetch, isFetching } = usePurchaseRFQs({ limit: 50 }); const { data: vendorsRes } = usePurchaseVendors({ status: "active", limit: 200 }); const { data: invitesRes } = usePurchaseRfqInvites(selected); const { data: quotesRes } = usePurchaseRfqQuotes(selected);
  const invite = useInviteRfqVendors(); const createQuote = useCreatePurchaseQuote(); const updateQuote = useUpdatePurchaseQuote(); const awardQuote = useAwardPurchaseQuote();
  const active = (data?.data ?? []).find(r => r.id === selected); const quotes = quotesRes?.data ?? []; const invites = invitesRes?.data ?? [];
  const run = async (action: () => Promise<unknown>, success: string, fallback: string) => { try { await action(); onNotice({ type: "success", text: success }); } catch (e) { onNotice({ type: "error", text: messageOf(e, fallback) }); } };
  if (isError) return <ErrorState label="RFQs" onRetry={() => refetch()} />;
  return <div className="space-y-3"><Panel><Toolbar title="Supplier sourcing" count={data?.total} loading={isFetching} onRefresh={() => refetch()} action={<span className="text-[11px] text-white/30">Select an RFQ to compare responses</span>} /><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b border-white/[0.05]">{["RFQ", "Scope", "Due date", "Estimate", "Supplier", "Status"].map(h => <th key={h} className="px-4 py-2.5 text-left text-[10px] font-semibold uppercase tracking-wider text-white/30">{h}</th>)}</tr></thead><tbody>{isLoading ? <SkeletonRows columns={6} /> : (data?.data ?? []).length === 0 ? <tr><td colSpan={6}><EmptyState title="No RFQs to work" detail="RFQs created from approved demand will appear here." /></td></tr> : (data?.data ?? []).map(rfq => <tr data-testid={`row-rfq-${rfq.id}`} key={rfq.id} onClick={() => setSelected(rfq.id)} className={cn("cursor-pointer border-b border-white/[0.045] transition-colors hover:bg-white/[0.025]", selected === rfq.id && "bg-cyan-400/[0.035]")}><td className="px-4 py-3 font-mono text-xs font-semibold text-cyan-300">{rfq.rfqNumber}</td><td className="max-w-[210px] truncate px-4 py-3 text-xs text-white/60">{rfq.itemsDescription || "Scope not specified"}</td><td className="px-4 py-3 text-xs text-white/40">{rfq.dueDate?.slice(0, 10) || "—"}</td><td className="px-4 py-3 text-xs tabular-nums text-white/65">{money(rfq.estimatedValue)}</td><td className="px-4 py-3 text-xs text-white/55">{rfq.vendorName || "Multi-supplier"}</td><td className="px-4 py-3"><Badge value={rfq.status} /></td></tr>)}</tbody></table></div></Panel>
    {active && <Panel className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-white/[0.07] px-4 py-4"><div><p className="font-mono text-xs text-cyan-300">{active.rfqNumber}</p><h3 className="mt-1 text-sm font-semibold text-white">{active.itemsDescription || "Supplier comparison"}</h3><p className="mt-1 text-xs text-white/35">{invites.length} invited · {quotes.length} quotes received</p></div><div className="flex items-center gap-2"><Badge value={active.status} /><button data-testid="button-close-rfq-detail" onClick={() => setSelected(null)} className="rounded-md p-1 text-white/30 hover:text-white"><X className="h-4 w-4" /></button></div></div><div className="flex flex-wrap gap-2 px-4 py-3">{canCreate && <><Button data-testid="button-invite-rfq-vendors" onClick={() => { setVendorIds([]); setInviteOpen(true); }} size="sm" className="h-8 gap-1.5 bg-violet-500/15 text-xs text-violet-200 hover:bg-violet-500/25"><UserPlus className="h-3.5 w-3.5" /> Invite suppliers</Button><Button data-testid="button-record-quote" onClick={() => { setEditQuote(null); setQuoteOpen(true); }} size="sm" className="h-8 gap-1.5 bg-cyan-500/15 text-xs text-cyan-200 hover:bg-cyan-500/25"><Plus className="h-3.5 w-3.5" /> Record quote</Button></>}</div><div className="border-t border-white/[0.05] px-4 py-3"><div className="mb-2 flex items-center justify-between"><p className="text-[10px] font-semibold uppercase tracking-wider text-white/30">Quote comparison</p><span className="text-[10px] text-white/25">Total landed value</span></div>{quotes.length === 0 ? <p className="py-5 text-center text-xs text-white/30">No supplier quotes received yet.</p> : <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-xs"><thead><tr className="border-b border-white/[0.05] text-left text-[10px] uppercase tracking-wider text-white/25"><th className="pb-2">Supplier</th><th className="pb-2">Quote</th><th className="pb-2">Delivery</th><th className="pb-2">Payment terms</th><th className="pb-2 text-right">Total</th><th className="pb-2"></th></tr></thead><tbody>{quotes.map(q => <tr data-testid={`row-quote-${q.id}`} key={q.id} className="border-b border-white/[0.04]"><td className="py-3 font-medium text-white/70">{q.vendorName}</td><td className="py-3 font-mono text-cyan-300/80">{q.quoteNumber}</td><td className="py-3 text-white/45">{q.deliveryDays == null ? "—" : `${q.deliveryDays} days`}</td><td className="py-3 text-white/45">{q.paymentTerms || "—"}</td><td className="py-3 text-right font-semibold tabular-nums text-white/80">{money(q.totalAmount)}</td><td className="py-3 text-right"><div className="flex justify-end gap-1">{canEdit && q.status === "draft" && <button data-testid={`button-edit-quote-${q.id}`} onClick={() => { setEditQuote(q); setQuoteOpen(true); }} className="rounded-md p-1.5 text-white/30 hover:bg-white/[0.07] hover:text-white"><Pencil className="h-3.5 w-3.5" /></button>}{canEdit && q.status !== "awarded" && <button data-testid={`button-award-quote-${q.id}`} onClick={() => { setAward(q); setAwardReason(""); }} className="rounded-md p-1.5 text-emerald-300/70 hover:bg-emerald-500/10 hover:text-emerald-200" title="Award quote"><CheckCircle2 className="h-3.5 w-3.5" /></button>}</div></td></tr>)}</tbody></table></div>}</div></Panel>}
    {inviteOpen && <Modal title="Invite suppliers" eyebrow="Source / RFQ distribution" onClose={() => setInviteOpen(false)}><form onSubmit={e => { e.preventDefault(); void run(() => invite.mutateAsync({ rfqId: active?.id ?? 0, vendorIds }), "Supplier invitations sent", "Could not send invitations").then(() => setInviteOpen(false)); }} className="space-y-4 p-5"><p className="text-xs leading-5 text-white/40">Select the active suppliers who should receive this RFQ.</p><div className="max-h-64 space-y-1 overflow-y-auto">{(vendorsRes?.data ?? []).map(v => <label key={v.id} className="flex cursor-pointer items-center gap-3 rounded-lg px-3 py-2.5 text-xs text-white/65 hover:bg-white/[0.05]"><input data-testid={`checkbox-invite-vendor-${v.id}`} type="checkbox" checked={vendorIds.includes(v.id)} onChange={e => setVendorIds(ids => e.target.checked ? [...ids, v.id] : ids.filter(id => id !== v.id))} className="accent-cyan-400" /><span>{v.name}</span><span className="ml-auto text-[10px] text-white/25">{v.category}</span></label>)}</div><FormActions busy={invite.isPending} onClose={() => setInviteOpen(false)} label={`Invite ${vendorIds.length || ""} supplier${vendorIds.length === 1 ? "" : "s"}`} /></form></Modal>}
    <QuoteForm open={quoteOpen} quote={editQuote} rfqId={active?.id ?? 0} vendors={vendorsRes?.data ?? []} onClose={() => setQuoteOpen(false)} busy={createQuote.isPending || updateQuote.isPending} error={createQuote.error ? messageOf(createQuote.error, "Could not record supplier quote") : updateQuote.error ? messageOf(updateQuote.error, "Could not update supplier quote") : null} onSubmit={value => void run(async () => { if (editQuote) await updateQuote.mutateAsync({ id: editQuote.id, data: value }); else await createQuote.mutateAsync(value); setQuoteOpen(false); }, editQuote ? "Supplier quote updated" : "Supplier quote recorded", "Could not save supplier quote")} />
    {award && <Modal title={`Award ${award.quoteNumber}`} eyebrow="Source / Award decision" onClose={() => setAward(null)}><form onSubmit={e => { e.preventDefault(); void run(() => awardQuote.mutateAsync({ rfqId: active?.id ?? 0, quoteId: award.id, awardReason }), "Quote awarded and PO created", "Could not award quote").then(() => setAward(null)); }} className="space-y-4 p-5"><div className="rounded-lg border border-emerald-500/15 bg-emerald-500/[0.06] p-3 text-xs text-white/60"><p className="font-semibold text-emerald-200">{award.vendorName} · {money(award.totalAmount)}</p><p className="mt-1 text-white/35">This decision creates the purchase order and closes the sourcing handoff.</p></div><Field label="Award reason"><Input data-testid="input-award-reason" required value={awardReason} onChange={e => setAwardReason(e.target.value)} placeholder="Document the commercial decision" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field>{awardQuote.error && <p className="text-xs text-red-300">{messageOf(awardQuote.error, "Could not award quote")}</p>}<FormActions busy={awardQuote.isPending} onClose={() => setAward(null)} label="Award and create PO" /></form></Modal>}
  </div>;
}

function InvoiceEdit({ invoice, onClose, onSubmit, busy }: { invoice: PurchaseInvoice; onClose: () => void; onSubmit: (data: { dueDate?: string | null; notes?: string | null; status?: PurchaseInvoice["status"] }) => void; busy: boolean }) {
  const [dueDate, setDueDate] = useState(invoice.dueDate?.slice(0, 10) ?? ""); const [notes, setNotes] = useState(invoice.notes ?? ""); const [status, setStatus] = useState(invoice.status);
  return <Modal title={`Update ${invoice.invoiceNumber}`} eyebrow="Pay / Invoice control" onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSubmit({ dueDate: dueDate || null, notes: notes || null, status }); }} className="space-y-4 p-5"><SelectField label="Status" value={status} onChange={v => setStatus(v as PurchaseInvoice["status"])}>{["draft", "received", "exception", "blocked"].map(v => <option key={v} value={v}>{v.replaceAll("_", " ")}</option>)}</SelectField><Field label="Due date"><Input data-testid="input-edit-invoice-due-date" type="date" value={dueDate} onChange={e => setDueDate(e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field><Field label="Notes"><Input data-testid="input-edit-invoice-notes" value={notes} onChange={e => setNotes(e.target.value)} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><FormActions busy={busy} onClose={onClose} label="Save invoice" /></form></Modal>;
}

function InvoicesView({ canCreate, canEdit, canDelete, onNotice }: { canCreate: boolean; canEdit: boolean; canDelete: boolean; onNotice: (notice: Notice) => void }) {
  const [selected, setSelected] = useState<number | null>(null); const [createOpen, setCreateOpen] = useState(false); const [editOpen, setEditOpen] = useState(false);
  const { data, isLoading, isError, refetch, isFetching } = usePurchaseInvoices(); const { data: detail } = usePurchaseInvoice(selected); const { data: ordersRes } = usePurchaseOrders({ limit: 100 }); const { data: vendorsRes } = usePurchaseVendors({ status: "active", limit: 200 }); const create = useCreatePurchaseInvoice(); const update = useUpdatePurchaseInvoice(); const remove = useDeletePurchaseInvoice(); const match = useMatchPurchaseInvoice(); const approve = useApprovePurchaseInvoice();
  const rows = data?.data ?? []; const active = detail?.data ?? rows.find(i => i.id === selected) ?? null;
  const run = async (action: () => Promise<unknown>, success: string, fallback: string) => { try { await action(); onNotice({ type: "success", text: success }); } catch (e) { onNotice({ type: "error", text: messageOf(e, fallback) }); } };
  if (isError) return <ErrorState label="invoices" onRetry={() => refetch()} />;
  return <div className="space-y-3"><Panel><Toolbar title="Invoice control" count={data?.total} loading={isFetching} onRefresh={() => refetch()} action={canCreate ? <Button data-testid="button-new-invoice" onClick={() => setCreateOpen(true)} size="sm" className="h-8 gap-1.5 bg-[#2563eb] text-xs hover:bg-[#1d4ed8]"><Plus className="h-3.5 w-3.5" /> Record invoice</Button> : null} /><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-sm"><thead><tr className="border-b border-white/[0.05]">{["Invoice", "Supplier", "PO", "Due date", "Amount", "Match", "Status", ""].map(h => <th key={h} className="px-4 py-2.5 text-left text-[10px] font-semibold uppercase tracking-wider text-white/30">{h}</th>)}</tr></thead><tbody>{isLoading ? <SkeletonRows columns={8} /> : rows.length === 0 ? <tr><td colSpan={8}><EmptyState title="No supplier invoices" detail="Invoice intake and three-way matching are managed here." action={canCreate ? <button data-testid="button-empty-new-invoice" onClick={() => setCreateOpen(true)} className="mt-3 text-xs text-cyan-300">Record first invoice</button> : undefined} /></td></tr> : rows.map(row => <tr data-testid={`row-invoice-${row.id}`} key={row.id} onClick={() => setSelected(row.id)} className={cn("group cursor-pointer border-b border-white/[0.045] transition-colors hover:bg-white/[0.025]", selected === row.id && "bg-cyan-400/[0.035]")}><td className="px-4 py-3 font-mono text-xs font-semibold text-cyan-300">{row.invoiceNumber}</td><td className="px-4 py-3 text-xs text-white/65">{row.vendorName}</td><td className="px-4 py-3 text-xs text-white/40">{row.poId ? `PO #${row.poId}` : "Unlinked"}</td><td className="px-4 py-3 text-xs text-white/40">{row.dueDate?.slice(0, 10) || "—"}</td><td className="px-4 py-3 text-right text-xs font-semibold tabular-nums text-white/75">{money(row.totalAmount)}</td><td className="px-4 py-3"><Badge value={row.matchStatus || "unmatched"} /></td><td className="px-4 py-3"><Badge value={row.status} /></td><td className="px-4 py-3"><div className="flex justify-end gap-1 opacity-0 transition-opacity group-hover:opacity-100">{canEdit && <button data-testid={`button-edit-invoice-${row.id}`} onClick={e => { e.stopPropagation(); setSelected(row.id); setEditOpen(true); }} className="rounded-md p-1.5 text-white/30 hover:bg-white/[0.07] hover:text-white"><Pencil className="h-3.5 w-3.5" /></button>}{canDelete && row.status === "draft" && <button data-testid={`button-delete-invoice-${row.id}`} onClick={e => { e.stopPropagation(); if (window.confirm(`Delete ${row.invoiceNumber}?`)) void run(() => remove.mutateAsync(row.id), "Invoice deleted", "Could not delete invoice"); }} className="rounded-md p-1.5 text-white/30 hover:bg-red-500/10 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button>}</div></td></tr>)}</tbody></table></div></Panel>
    {active && <Panel className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-white/[0.07] px-4 py-4"><div><p className="font-mono text-xs text-cyan-300">{active.invoiceNumber}</p><h3 className="mt-1 text-sm font-semibold text-white">{active.vendorName}</h3><p className="mt-1 text-xs text-white/35">{active.poId ? `PO #${active.poId}` : "No PO linked"} · Due {active.dueDate?.slice(0, 10) || "not set"}</p></div><div className="flex items-center gap-2"><Badge value={active.status} /><button data-testid="button-close-invoice-detail" onClick={() => setSelected(null)} className="rounded-md p-1 text-white/30 hover:text-white"><X className="h-4 w-4" /></button></div></div><div className="flex flex-wrap gap-2 px-4 py-3">{canEdit && <Button data-testid={`button-match-invoice-${active.id}`} onClick={() => void run(() => match.mutateAsync(active.id), "Three-way match completed", "Could not match invoice")} size="sm" className="h-8 gap-1.5 bg-cyan-500/15 text-xs text-cyan-200 hover:bg-cyan-500/25"><ShieldCheck className="h-3.5 w-3.5" /> Run three-way match</Button>}{canEdit && active.status === "matched" && <Button data-testid={`button-approve-invoice-${active.id}`} onClick={() => void run(() => approve.mutateAsync(active.id), "Invoice approved for payment", "Could not approve invoice")} size="sm" className="h-8 gap-1.5 bg-emerald-500/15 text-xs text-emerald-200 hover:bg-emerald-500/25"><Check className="h-3.5 w-3.5" /> Approve invoice</Button>}<span className="ml-auto flex items-center gap-2 text-xs text-white/40">Variance <strong className={cn("tabular-nums", Number(active.matchVariance) ? "text-red-300" : "text-emerald-300")}>{money(active.matchVariance)}</strong></span></div>{active.lines?.length ? <div className="border-t border-white/[0.05] px-4 py-3">{active.lines.map(line => <div key={line.id} className="flex justify-between border-b border-white/[0.04] py-2 text-xs last:border-0"><span className="text-white/60">{line.description}</span><span className="text-white/40">{line.quantity} × {money(line.unitPrice)}</span></div>)}</div> : null}</Panel>}
     <InvoiceForm open={createOpen} orders={(ordersRes?.data ?? []).map(o => ({ id: o.id, poNumber: o.poNumber, vendorId: o.vendorId, vendorName: o.vendorName }))} vendors={vendorsRes?.data ?? []} onClose={() => setCreateOpen(false)} busy={create.isPending} error={create.error ? messageOf(create.error, "Could not record invoice") : null} onSubmit={value => void run(() => create.mutateAsync(value), "Invoice recorded", "Could not record invoice").then(() => setCreateOpen(false))} />
    {active && <InvoiceEdit invoice={active} onClose={() => setEditOpen(false)} busy={update.isPending} onSubmit={value => void run(() => update.mutateAsync({ id: active.id, data: value }), "Invoice updated", "Could not update invoice").then(() => setEditOpen(false))} />}
  </div>;
}

function PaymentForm({ open, invoices, onClose, onSubmit, busy, error }: { open: boolean; invoices: PurchaseInvoice[]; onClose: () => void; onSubmit: (value: PurchasePaymentFormValues) => void; busy: boolean; error: string | null }) {
  const [form, setForm] = useState<PurchasePaymentFormValues>({ invoiceId: 0, amount: "0", paymentDate: today(), method: "bank_transfer", notes: "" });
  if (!open) return null;
  return <Modal title="Initiate payment" eyebrow="Pay / Settlement" onClose={onClose}><form onSubmit={e => { e.preventDefault(); onSubmit(form); }} className="space-y-4 p-5"><SelectField label="Invoice" value={String(form.invoiceId || "")} onChange={v => setForm(f => ({ ...f, invoiceId: Number(v) }))}><option value="">Select approved invoice</option>{invoices.map(i => <option key={i.id} value={i.id}>{i.invoiceNumber} · {i.vendorName} · {money(i.totalAmount)}</option>)}</SelectField><div className="grid gap-3 sm:grid-cols-2"><Field label="Amount"><Input data-testid="input-payment-amount" required type="number" min="0.01" step="any" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field><Field label="Payment date"><Input data-testid="input-payment-date" required type="date" value={form.paymentDate} onChange={e => setForm(f => ({ ...f, paymentDate: e.target.value }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs [color-scheme:dark]" /></Field></div><SelectField label="Method" value={form.method} onChange={v => setForm(f => ({ ...f, method: v as PurchasePaymentFormValues["method"] }))}><option value="bank_transfer">Bank transfer</option><option value="manual">Manual</option><option value="razorpay">Razorpay</option></SelectField><Field label="Notes"><Input data-testid="input-payment-notes" value={form.notes ?? ""} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field>{error && <p className="text-xs text-red-300">{error}</p>}<FormActions busy={busy} onClose={onClose} label="Initiate payment" /></form></Modal>;
}

function PaymentsView({ canCreate, canEdit, onNotice, razorpayConfigured }: { canCreate: boolean; canEdit: boolean; onNotice: (notice: Notice) => void; razorpayConfigured: boolean }) {
  const [createOpen, setCreateOpen] = useState(false); const [failPayment, setFailPayment] = useState<PurchasePayment | null>(null); const [failureReason, setFailureReason] = useState("");
  const { data, isLoading, isError, refetch, isFetching } = usePurchasePayments(); const { data: invoicesRes } = usePurchaseInvoices({ status: "approved" }); const create = useCreatePurchasePayment(); const razorpay = useCreateRazorpayOrder(); const paid = useMarkPurchasePaymentPaid(); const fail = useFailPurchasePayment();
  const rows = data?.data ?? [];
  const run = async (action: () => Promise<unknown>, success: string, fallback: string) => { try { await action(); onNotice({ type: "success", text: success }); } catch (e) { onNotice({ type: "error", text: messageOf(e, fallback) }); } };
  if (isError) return <ErrorState label="payments" onRetry={() => refetch()} />;
  return <><div className="space-y-3"><Panel><Toolbar title="Payment run" count={data?.total} loading={isFetching} onRefresh={() => refetch()} action={canCreate ? <Button data-testid="button-new-payment" onClick={() => setCreateOpen(true)} size="sm" className="h-8 gap-1.5 bg-[#2563eb] text-xs hover:bg-[#1d4ed8]"><Plus className="h-3.5 w-3.5" /> Initiate payment</Button> : null} /><div className="overflow-x-auto"><table className="w-full min-w-[820px] text-sm"><thead><tr className="border-b border-white/[0.05]">{["Payment", "Invoice", "Supplier", "Method", "Date", "Amount", "Status", ""].map(h => <th key={h} className="px-4 py-2.5 text-left text-[10px] font-semibold uppercase tracking-wider text-white/30">{h}</th>)}</tr></thead><tbody>{isLoading ? <SkeletonRows columns={8} /> : rows.length === 0 ? <tr><td colSpan={8}><EmptyState title="No payment run activity" detail="Approved invoices become payable here with a complete settlement trail." /></td></tr> : rows.map(row => <tr data-testid={`row-payment-${row.id}`} key={row.id} className="group border-b border-white/[0.045] transition-colors hover:bg-white/[0.025]"><td className="px-4 py-3 font-mono text-xs font-semibold text-cyan-300">{row.paymentNumber}</td><td className="px-4 py-3 font-mono text-xs text-white/55">{row.invoiceNumber}</td><td className="px-4 py-3 text-xs text-white/65">{row.vendorName}</td><td className="px-4 py-3 text-xs capitalize text-white/45">{row.method.replaceAll("_", " ")}</td><td className="px-4 py-3 text-xs text-white/40">{row.paymentDate?.slice(0, 10)}</td><td className="px-4 py-3 text-right text-xs font-semibold tabular-nums text-white/75">{money(row.amount)}</td><td className="px-4 py-3"><Badge value={row.status} /></td><td className="px-4 py-3"><div className="flex justify-end gap-1 opacity-0 transition-opacity group-hover:opacity-100">{canEdit && row.method === "razorpay" && ["initiated", "processing"].includes(row.status) && razorpayConfigured && <button data-testid={`button-create-razorpay-order-${row.id}`} onClick={() => void run(() => razorpay.mutateAsync(row.id), "Razorpay order created", "Could not create Razorpay order")} className="rounded-md p-1.5 text-violet-300/70 hover:bg-violet-500/10 hover:text-violet-200" title="Create Razorpay order"><Banknote className="h-3.5 w-3.5" /></button>}{canEdit && ["initiated", "processing"].includes(row.status) && <button data-testid={`button-mark-payment-paid-${row.id}`} onClick={() => void run(() => paid.mutateAsync({ id: row.id }), "Payment marked paid", "Could not mark payment paid")} className="rounded-md p-1.5 text-emerald-300/70 hover:bg-emerald-500/10 hover:text-emerald-200" title="Mark paid"><Check className="h-3.5 w-3.5" /></button>}{canEdit && !["paid", "failed", "cancelled"].includes(row.status) && <button data-testid={`button-fail-payment-${row.id}`} onClick={() => { setFailPayment(row); setFailureReason(""); }} className="rounded-md p-1.5 text-red-300/60 hover:bg-red-500/10 hover:text-red-200" title="Fail payment"><XCircle className="h-3.5 w-3.5" /></button>}</div></td></tr>)}</tbody></table></div></Panel><div className="flex items-center gap-2 rounded-lg border border-white/[0.07] bg-white/[0.025] px-3 py-2 text-[11px] text-white/35"><ShieldCheck className="h-3.5 w-3.5 text-cyan-300/70" /> Payment status changes are recorded against the invoice and refresh the source-to-pay summary.</div></div>
    <PaymentForm open={createOpen} invoices={invoicesRes?.data ?? []} onClose={() => setCreateOpen(false)} busy={create.isPending} error={create.error ? messageOf(create.error, "Could not initiate payment") : null} onSubmit={value => void run(() => create.mutateAsync(value), "Payment initiated", "Could not initiate payment").then(() => setCreateOpen(false))} />
    {failPayment && <Modal title={`Fail ${failPayment.paymentNumber}`} eyebrow="Pay / Exception" onClose={() => setFailPayment(null)}><form onSubmit={e => { e.preventDefault(); void run(() => fail.mutateAsync({ id: failPayment.id, reason: failureReason }), "Payment marked failed", "Could not fail payment").then(() => setFailPayment(null)); }} className="space-y-4 p-5"><Field label="Failure reason"><Input data-testid="input-payment-failure-reason" required value={failureReason} onChange={e => setFailureReason(e.target.value)} placeholder="Capture bank or provider response" className="h-9 border-white/[0.1] bg-white/[0.045] text-xs" /></Field>{fail.error && <p className="text-xs text-red-300">{messageOf(fail.error, "Could not fail payment")}</p>}<FormActions busy={fail.isPending} onClose={() => setFailPayment(null)} label="Mark failed" /></form></Modal>}
  </> ;
}

function Toolbar({ title, count, loading, onRefresh, action }: { title: string; count?: number; loading: boolean; onRefresh: () => void; action?: ReactNode }) {
  return <div className="flex flex-wrap items-center gap-3 border-b border-white/[0.05] px-4 py-3"><div><h2 className="text-sm font-semibold text-white/80">{title}</h2>{typeof count === "number" && <p className="mt-0.5 text-[10px] text-white/30">{count} records in view</p>}</div><div className="ml-auto flex items-center gap-2">{action}<button data-testid={`button-refresh-${title.toLowerCase().replaceAll(" ", "-")}`} onClick={onRefresh} className={cn("rounded-md p-1.5 text-white/30 transition-colors hover:bg-white/[0.07] hover:text-white", loading && "animate-spin")}><RefreshCw className="h-3.5 w-3.5" /></button></div></div>;
}

function ErrorState({ label, onRetry }: { label: string; onRetry: () => void }) {
  return <Panel><div className="flex min-h-[240px] flex-col items-center justify-center text-center"><AlertTriangle className="mb-3 h-6 w-6 text-red-300" /><p data-testid="status-load-error" className="text-sm text-white/70">Could not load {label}</p><p className="mt-1 text-xs text-white/30">The last successful view is preserved by the server. Try again.</p><Button data-testid="button-retry-load" onClick={onRetry} size="sm" variant="outline" className="mt-4 h-8 border-white/[0.12] bg-transparent text-xs text-white/55 hover:bg-white/[0.06] hover:text-white">Retry</Button></div></Panel>;
}

export default function SourceToPayTab() {
  const [tab, setTab] = useState<WorkspaceTab>("requisitions"); const [notice, setNotice] = useState<Notice>(null);
  const { data: summary, isLoading: summaryLoading, isError: summaryError, refetch: refetchSummary } = useSourceToPaySummary(); const { data: permissions, isLoading: permissionsLoading } = usePurchasePermissions();
  const perms = permissions?.data ?? { canView: true, canCreate: false, canEdit: false, canDelete: false }; const summaryData = summary?.data;
  const stages = useMemo(() => [{ key: "requisitions" as const, label: "Demand", icon: ClipboardCheck, count: summaryData?.requisitions.pendingApproval ?? 0, detail: "Requisitions & approvals" }, { key: "sourcing" as const, label: "Source", icon: Users, count: summaryData?.quotes.active ?? 0, detail: "RFQs & quote awards" }, { key: "invoices" as const, label: "Receive & match", icon: PackageCheck, count: summaryData?.invoices.exceptions ?? 0, detail: "Invoice exceptions" }, { key: "payments" as const, label: "Pay", icon: CircleDollarSign, count: summaryData?.payments.pending ?? 0, detail: "Settlement queue" }], [summaryData]);
  if (permissionsLoading) return <div data-testid="source-to-pay-loading" className="space-y-4"><div className="h-20 animate-pulse rounded-xl bg-white/[0.04]" /><div className="h-56 animate-pulse rounded-xl bg-white/[0.04]" /></div>;
  if (!perms.canView) return <Panel><div className="flex min-h-[360px] flex-col items-center justify-center text-center"><ShieldCheck className="mb-3 h-8 w-8 text-amber-300/80" /><p data-testid="status-source-to-pay-forbidden" className="text-sm font-semibold text-white/75">Source-to-pay access is restricted</p><p className="mt-1 max-w-sm text-xs text-white/35">Ask an organisation administrator for procurement workspace access.</p></div></Panel>;
  return <div data-testid="source-to-pay-workspace" className="space-y-5">
    <div className="flex flex-wrap items-end justify-between gap-3"><div><div className="flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.2em] text-cyan-300/70"><span className="h-1.5 w-1.5 rounded-full bg-cyan-300" /> Operating cockpit</div><h2 data-testid="text-source-to-pay-title" className="mt-1 text-xl font-semibold tracking-tight text-white">Source to pay</h2><p className="mt-1 max-w-2xl text-xs text-white/40">Move every purchase from employee demand to a paid supplier invoice with approval context intact.</p></div><div className="flex items-center gap-2 text-[10px] text-white/30"><span className="font-mono">LIVE WORK QUEUE</span><span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /></div></div>
    <SummaryStrip summary={summary} loading={summaryLoading} />
    {summaryError && <div className="flex items-center gap-2 rounded-lg border border-amber-500/20 bg-amber-500/[0.07] px-3 py-2 text-xs text-amber-200"><AlertTriangle className="h-3.5 w-3.5" /> Summary is unavailable. <button data-testid="button-retry-summary" onClick={() => refetchSummary()} className="underline underline-offset-2">Retry</button></div>}
    <div className="relative grid grid-cols-2 gap-2 rounded-xl border border-white/[0.07] bg-[#080d1b] p-2 lg:grid-cols-4">{stages.map((stage, index) => <button data-testid={`tab-source-to-pay-${stage.key}`} key={stage.key} onClick={() => setTab(stage.key)} className={cn("relative flex min-h-[76px] items-center gap-3 rounded-lg px-3 text-left transition-colors", tab === stage.key ? "bg-cyan-400/[0.09] ring-1 ring-cyan-300/20" : "hover:bg-white/[0.04]")}><div className={cn("flex h-8 w-8 shrink-0 items-center justify-center rounded-lg", tab === stage.key ? "bg-cyan-400/15 text-cyan-200" : "bg-white/[0.05] text-white/35")}><stage.icon className="h-4 w-4" /></div><div className="min-w-0"><p className={cn("text-xs font-semibold", tab === stage.key ? "text-cyan-100" : "text-white/65")}>{stage.label}</p><p className="mt-0.5 truncate text-[10px] text-white/30">{stage.detail}</p></div><span className={cn("ml-auto self-start rounded-full px-1.5 py-0.5 text-[10px] font-semibold tabular-nums", stage.count > 0 ? "bg-amber-400/10 text-amber-200" : "bg-white/[0.05] text-white/30")}>{stage.count}</span>{index < stages.length - 1 && <ArrowRight className="absolute -right-3 z-10 hidden h-3.5 w-3.5 text-white/15 lg:block" />}</button>)}</div>
    <InlineNotice notice={notice} onDismiss={() => setNotice(null)} />
    {tab === "requisitions" && <RequisitionsView canCreate={perms.canCreate} canEdit={perms.canEdit} canDelete={perms.canDelete} onNotice={setNotice} />}
    {tab === "sourcing" && <SourcingView canCreate={perms.canCreate} canEdit={perms.canEdit} onNotice={setNotice} />}
    {tab === "invoices" && <InvoicesView canCreate={perms.canCreate} canEdit={perms.canEdit} canDelete={perms.canDelete} onNotice={setNotice} />}
    {tab === "payments" && <PaymentsView canCreate={perms.canCreate} canEdit={perms.canEdit} onNotice={setNotice} razorpayConfigured={summaryData?.razorpayConfigured ?? false} />}
  </div>;
}